using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Xml;
namespace OwnLabView {
internal sealed class ProjectLayout {
 internal readonly Dictionary<string,string> Members=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
 internal readonly HashSet<string> Folders=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
 static string Check(string path){if(path==null||path.Length>240||path.Split('/').Length>16)throw new ArgumentException("Folder path exceeds supported depth/length.");if(path.Length>0)foreach(string part in path.Split('/')){if(String.IsNullOrWhiteSpace(part)||part=="."||part==".."||part.IndexOfAny(Path.GetInvalidFileNameChars())>=0||part.Trim()!=part||part.EndsWith("."))throw new ArgumentException("Folder requires slash-separated valid names.");}return path;}
 internal static XmlDocument Read(string path){var xml=new XmlDocument{XmlResolver=null};using(var reader=XmlReader.Create(path,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=8*1024*1024}))xml.Load(reader);return xml;}
 internal static string FolderOf(XmlNode item){var parts=new List<string>();for(XmlNode n=item.ParentNode;n!=null&&n.Attributes!=null&&n.Attributes["Type"]!=null&&n.Attributes["Type"].Value=="Folder";n=n.ParentNode)parts.Insert(0,n.Attributes["Name"].Value);return String.Join("/",parts);}
 internal static string Resolve(string project,string url){string decoded=Uri.UnescapeDataString(url);Uri absolute;if(Uri.TryCreate(decoded,UriKind.Absolute,out absolute)&&absolute.IsFile)return Path.GetFullPath(absolute.LocalPath);return Path.GetFullPath(Path.Combine(project,decoded.Replace('/',Path.DirectorySeparatorChar)));}
 internal static ProjectLayout Parse(Dictionary<string,object> args,string[] members,ProjectSource source){var result=new ProjectLayout();if(source!=null){var xml=Read(source.Path);foreach(XmlNode item in xml.SelectNodes("/Project/Item[@Type='My Computer']//Item[@Type='Folder' and not(ancestor::Item[@Type='Dependencies'])]"))result.Folders.Add(Check(FolderOf(item)+ (FolderOf(item).Length==0?"":"/")+item.Attributes["Name"].Value));foreach(XmlNode item in xml.SelectNodes("/Project/Item[@Type='My Computer']//Item[(@Type='VI' or @Type='LVClass' or @Type='Library') and not(ancestor::Item[@Type='Dependencies'])]")){string path=Resolve(source.Path,item.Attributes["URL"].Value);if(members.Contains(path,StringComparer.OrdinalIgnoreCase))result.Members[path]=FolderOf(item);}}
 if(args.ContainsKey("folders")){result.Folders.Clear();foreach(object folder in Data.Array(args["folders"])){if(!(folder is string))throw new ArgumentException("folders entries must be strings.");result.Folders.Add(Check((string)folder));}}
 if(args.ContainsKey("member_folders")){result.Members.Clear();foreach(var pair in Data.Map(args["member_folders"])){if(!members.Contains(pair.Key,StringComparer.OrdinalIgnoreCase)||!(pair.Value is string))throw new ArgumentException("member_folders keys must be requested paths and values folder names.");result.Members[pair.Key]=Check((string)pair.Value);}}
 foreach(string member in members)if(!result.Members.ContainsKey(member))result.Members[member]="";foreach(string folder in result.Members.Values)result.Folders.Add(folder);foreach(string full in result.Folders.ToArray()){var parts=full.Split('/');for(int i=1;i<parts.Length;i++)result.Folders.Add(String.Join("/",parts.Take(i)));}if(result.Folders.Count>64)throw new ArgumentException("At most64 project folders.");return result;}
 internal void Apply(string project){var xml=Read(project);var computer=xml.SelectSingleNode("/Project/Item[@Type='My Computer']");var items=computer.SelectNodes(".//Item[(@Type='VI' or @Type='LVClass' or @Type='Library') and not(ancestor::Item[@Type='Dependencies'])]").Cast<XmlNode>().ToArray();foreach(var item in items)item.ParentNode.RemoveChild(item);foreach(XmlNode folder in computer.SelectNodes("Item[@Type='Folder']"))computer.RemoveChild(folder);var parents=new Dictionary<string,XmlNode>(StringComparer.OrdinalIgnoreCase){{"",computer}};foreach(string full in Folders.OrderBy(x=>x)){string current="";foreach(string part in full.Split(new[]{'/'},StringSplitOptions.RemoveEmptyEntries)){string parent=current;current=current.Length==0?part:current+"/"+part;if(!parents.ContainsKey(current)){var node=xml.CreateElement("Item");node.SetAttribute("Name",part);node.SetAttribute("Type","Folder");parents[parent].AppendChild(node);parents.Add(current,node);}}}foreach(XmlNode item in items){string path=Resolve(project,item.Attributes["URL"].Value),folder;Members.TryGetValue(path,out folder);parents[folder??""].AppendChild(item);}foreach(XmlNode special in computer.SelectNodes("Item[@Type='Dependencies' or @Type='Build']").Cast<XmlNode>().ToArray())computer.AppendChild(special);xml.Save(project);}
 internal object Evidence(){return new{folders=Folders.Where(s=>s.Length>0).OrderBy(s=>s).ToArray(),member_folders=Members};}
}
}
